{
  "filecontent": null,
  "displayorder": 6,
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "parentpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "partialurl": "Validate-Pin",
  "isroot": false,
  "rootwebpageid": "5c8e49a7-1f09-713c-d804-3ac43710b320",
  "title": "Registration Success",
  "summary": "<p>This is a sample landing page designed to be a starting point for your website</p>",
  "copy": "{% include 'cmdspp_ToastModal' %}
<div class="cmdspp-validatepage-container cmdspp-registration-pages-bg">

    <div class="cmdspp-validatepage-left">
      <div class="cmdspp-validatepage-badge"><span class="cmds-portal-badge-dot">●</span>OFFICIAL GOVERNMENT PORTAL · SECURE CONNECTION</div>
      <h1 class="cmdspp-validatepage-title">
        Confirm<br />
        Verification PIN
      </h1>
      <p class="cmdspp-validatepage-subtitle">Verify PIN to create your account</p>
      <div class="cmdspp-benefits">
      <div><img src="/cmdspp_greenTickCircle"/>  HIPAA Compliant Infrastructure</div>
      <div><img src="/cmdspp_greenTickCircle"/>  256-bit TLS Encryption</div>
      <div><img src="/cmdspp_greenTickCircle"/>  ISO 27001:2022 Certified</div>
    </div>
    </div>
    <div class="cmdspp-validatepage-right">
      <div class="cmdspp-validatepage-card">
        <h2 class="cmdspp-validatepage-card-title">Enter PIN</h2>
        <p class="cmdspp-validatepage-card-text">Enter the 6-digit verification PIN sent to your email address</p>
        <div class="cmdspp-validatepage-pin-wrapper"><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /><input type="text" maxlength="1" class="cmdspp-validatepage-pin-input" /></div>
        <div class="cmdspp-validatepage-actions"><button type="button" id="cmdspp-validatepage-resendCode-id" class="cmdspp-validatepage-btn cmdspp-validatepage-btn-secondary">Resend Code</button><button id="cmdspp-validatepage-verifyCode-id" type="button" class="cmdspp-validatepage-btn cmdspp-validatepage-btn-primary">Verify Code</button></div>
      </div>
    </div>

</div>
<div class="row sectionBlockLayout text-start" style="display: none; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;"><div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px;"></div></div>
</div>",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "hiddenfromsitemap": true,
  "sharedpageconfiguration": false,
  "feedbackpolicy": 756150000,
  "customjavascript": "async function callPowerAutomatePinFlow(payload) {

    // const flowUrl = "https://68800e766659e6b2b28f47b46ad295.0f.environment.api.powerplatform.com:443/powerautomate/automations/direct/cu/23/workflows/5fec314660994d8188e4a3ffb4054ae1/triggers/manual/paths/invoke?api-version=1&sp=%2Ftriggers%2Fmanual%2Frun&sv=1.0&sig=uxn0GLnUIv74eO0B37L9aLI3LSZfaeBykWMV3sJqrC4";
    const flowUrl = window.flowConfig.cmdspp_createValidatePinForUser;

    try {

        const response = await fetch(flowUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status}`);
        }

        const result = await response.json();

        console.log("Flow Response:", result);

        return result;

    } catch (error) {

        console.error("Flow Call Failed:", error);

        throw error;
    }
}
document.addEventListener("DOMContentLoaded", async function () {

    const params = new URLSearchParams(window.location.search);

    const contactId = params.get("id");

    if (!contactId) {

        alert("Contact Id not found.");
        return;
    }

    const forgotPass = sessionStorage.getItem("forgotPassword");

    const res = await callPowerAutomatePinFlow({
            registrationId: contactId,
            transType:"set",
            isReset:forgotPass === "true" ? true :false
        })
        
    sessionStorage.removeItem("forgotPassword");

});

$(document).on(
    "click",
    "#cmdspp-validatepage-verifyCode-id",
    async function () {

        const pinInputs = document.querySelectorAll(
            ".cmdspp-validatepage-pin-input"
        );

        let pin = "";
        let hasEmptyField = false;

        pinInputs.forEach(input => {

            const value = input.value.trim();
            
           if (!value) {
             hasEmptyField = true;
             input.classList.add("cmdspp-field-error");
           } else {
             input.classList.remove("cmdspp-field-error");
           }

            pin += value;
        });

        if (hasEmptyField) {
            
          cmdsppShowToast("error","Verification code is required");

            // alert("Please enter all 6 digits.");
            return;
        }

        const params = new URLSearchParams(window.location.search);

        const id = params.get("id");

        const $button = $(this);
        $button.prop("disabled", true);

        let result = await callPowerAutomatePinFlow({
            pin: pin,
            registrationId:id,
            transType:"validate"
        });

        $button.prop("disabled", false);
        // Handle the response from the Power Automate flow
        if (result && typeof result.success !== 'undefined') {
            if (result.success === true) {
                var invitationCode = result.invitationCode;
                if (invitationCode) {
                    // Navigate to the native set password page
                    let url = '/Account/Register?invitation=' + invitationCode;
                    cmdsppNavigateWithToast("success","PIN verified successfully",url);
                } else {
                    cmdsppShowToast("error",'Invitation code is missing. Please contact support.');

                }
            } else {
                // Show error message from result or a generic error
                var errorMsg = result.message || 'Invalid PIN. Please try again.';
                cmdsppShowToast("error",errorMsg);
            }
        } else {
            // Handle unexpected response
            cmdsppShowToast("error",'Unexpected response from server. Please try again later.');
        }
    }
);

$(document).on(
    "input",
    ".cmdspp-validatepage-pin-input",
    function () {
        $(this).removeClass("cmdspp-field-error");
        const currentInput = $(this);

        // Keep only one digit
        currentInput.val(
            currentInput.val().replace(/\D/g, "").slice(0, 1)
        );

        // Move to next box if a digit was entered
        if (currentInput.val()) {

            currentInput
                .next(".cmdspp-validatepage-pin-input")
                .focus();

        }

    }
);

$(document).on(
    "click",
    "#cmdspp-validatepage-resendCode-id",
    async function () {

        const pinInputs = document.querySelectorAll(
            ".cmdspp-validatepage-pin-input"
        );

        pinInputs.forEach(input => {

            input.value = "";
            
        });

        const params = new URLSearchParams(window.location.search);

        const id = params.get("id");

        const $button = $(this);
        $button.prop("disabled", true);

        let result = await callPowerAutomatePinFlow({
            registrationId:id,
            transType:"set",
            isReset:true
        });

        $button.prop("disabled", false);

        if(result){
            if(result.message==="PIN sent"){
                cmdsppShowToast("success","PIN sent successfully");
            }
        }
    }
);",
  "customcss": ".cmdspp-login-btn{
    display: none !important
}

.cmdspp-validatepage-container {
    /* min-height: calc(100vh - 124px);
    position: relative;
    overflow: hidden;
    padding: 60px 80px; */
    display: flex;
    min-height: calc(100vh - 124px);
    align-items: center;
    justify-content: space-between;
    padding: clamp(40px, 11vh, 105px) clamp(24px, 5.5vw, 80px);
}

.cmdspp-validatepage-content {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 80px;
}

.cmdspp-validatepage-left {
    flex: 1;
    max-width: 550px;
}

.cmdspp-validatepage-badge {
    display:inline-block;
    background:#0B3A6F1A;
    border:1px solid #0B3A6F26;
    padding:7px 17px;
    border-radius:20px;
    color:#0B3A6FE5;
    margin-bottom:30px;
    font-weight: 400;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0.3px;
    text-transform: uppercase;
    span{
        color: #00D492 !important;
        margin-right: 8px;
    }
}

.cmdspp-validatepage-title {
    color: #0B3A6F;
    font-size: 54px;
    font-weight: 400 !important;
    line-height: 62px;
    margin-bottom: 34px;
}

.cmdspp-validatepage-subtitle {
    font-size: 16px;
    color: #0B3A6F;
    line-height: 26px;
    margin-bottom: 50px;
    font-weight: 400 !important;
}

.cmdspp-benefits div{
    margin-bottom: 10px;
    color: #0B3A6F;
    font-size: 14px;
    line-height: 20px;
    font-weight: 400 !important;
}

.cmdspp-validatepage-right {
    flex-shrink: 0;
}

.cmdspp-validatepage-card {
    position: relative;
    width: 498px;
    background: #ffffff;
    border-radius: 14px;
    padding: 32px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
    overflow: hidden;
}

.cmdspp-validatepage-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;

    width: 100%;
    height: 4px;

    background: linear-gradient(
        90deg,
        #1A3A6B 0%,
        #00A6F4 50%,
        #1A3A6B 100%
    );
}

.cmdspp-validatepage-card-title {
    font-weight: 400 !important;
    font-size: 22.4px;
    line-height: 33.6px;
    letter-spacing: 0px;
    text-align: center;
    text-transform: capitalize;
    margin: 0 0 5.7px;
    color: #0F1F3D;
}

.cmdspp-validatepage-card-text {
    font-weight: 400 !important;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0px;
    text-align: center;
    color: #5A7099;
    margin-bottom: 32px;
}

.cmdspp-validatepage-pin-wrapper {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 32px;
}

.cmdspp-validatepage-pin-input {
    width: 61px;
    height: 62px;
    border: 2px solid #B6C4D4;
    border-radius: 5px;
    text-align: center;
    font-size: 20px;
    color: #1d428a;
    outline: none;
}

.cmdspp-validatepage-pin-input:focus {
    box-shadow: 0px 0px 0px 1px #6C8EEF inset, 0px 0px 0px 2px #D6ECFF;
}

.cmdspp-validatepage-actions {
    display: flex;
    gap: 16px;
}

.cmdspp-validatepage-btn {
    flex: 1;
    height: 40px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 400 !important;
    font-size: 14px;
    line-height: 20px;
    letter-spacing: 0px;
    text-align: center;
    transition: all 0.2s ease;
}

.cmdspp-validatepage-btn-secondary {
    background: #ffffff;
    border: 1px solid #274463;
    color: #274463;
}

.cmdspp-validatepage-btn-secondary:hover {
    background: #f3f6fa;
}

.cmdspp-validatepage-btn-primary {
    background: #274463;
    border: none;
    color: #ffffff;
}

.cmdspp-validatepage-btn-primary:hover {
    background: #17356e;
}

.cmdspp-field-error {
    box-shadow: inset 0 0 0 1px #CD3D64, 0 0 0 2px #FDE2DD;
}


@media (max-width: 992px) {

    .cmdspp-validatepage-content {
        flex-direction: column;
        text-align: center;
    }

    .cmdspp-validatepage-card {
        width: 100%;
        max-width: 450px;
    }

    .cmdspp-validatepage-title {
        font-size: 48px;
    }

    .cmdspp-validatepage-container {
        padding: 40px 24px;
    }

    .cmdspp-validatepage-features li {
        text-align: left;
    }
}

@media (max-width: 576px) {

    .cmdspp-validatepage-pin-wrapper {
        gap: 8px;
    }

    .cmdspp-validatepage-pin-input {
        width: 40px;
        height: 40px;
    }

    .cmdspp-validatepage-actions {
        flex-direction: column;
    }

    .cmdspp-validatepage-title {
        font-size: 38px;
    }
}"
}
